function startOfDay(d) {
  return new Date(d.getFullYear(), d.getMonth(), d.getDate());
}

function daysInMonth(year, month) {
  return new Date(year, month + 1, 0).getDate();
}

module.exports = { startOfDay, daysInMonth };
const { daysInMonth } = require('./dates');

function prorate(amountCents, startDate, anchorDay) {
  const year = startDate.getFullYear();
  const month = startDate.getMonth();
  const inMonth = daysInMonth(year, month);
  const remaining = inMonth - startDate.getDate() + 1;
  return Math.round((amountCents * remaining) / inMonth);
}

module.exports = { prorate };
